--
-- Table structure for table `profiles`
--

DROP TABLE IF EXISTS `profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `profiles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `profession_id` bigint(20) unsigned DEFAULT NULL,
  `name` varchar(191) NOT NULL,
  `slug` varchar(191) DEFAULT NULL,
  `prof` text DEFAULT NULL,
  `company_name` varchar(191) DEFAULT NULL,
  `email` varchar(191) NOT NULL,
  `website` varchar(191) DEFAULT NULL,
  `last_name` varchar(191) DEFAULT NULL,
  `dob` date DEFAULT NULL,
  `phone` varchar(191) DEFAULT NULL,
  `whatsapp` varchar(50) DEFAULT NULL,
  `country_code` varchar(191) DEFAULT NULL,
  `facebook` varchar(191) DEFAULT NULL,
  `instagram` varchar(191) DEFAULT NULL,
  `twitter` varchar(191) DEFAULT NULL,
  `tiktok` varchar(191) DEFAULT NULL,
  `youtube` varchar(191) DEFAULT NULL,
  `rumble` varchar(190) DEFAULT NULL,
  `truth` varchar(190) DEFAULT NULL,
  `linkedin` varchar(190) DEFAULT NULL,
  `avatar` varchar(191) DEFAULT NULL,
  `zip_code` varchar(191) DEFAULT NULL,
  `color_code` varchar(191) NOT NULL DEFAULT '#212121',
  `address` text DEFAULT NULL,
  `about` text DEFAULT NULL,
  `is_employ` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `gender_id` bigint(20) unsigned DEFAULT NULL,
  `marital_status_id` bigint(20) unsigned DEFAULT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `company_user_id` bigint(20) unsigned DEFAULT NULL,
  `designation` varchar(191) DEFAULT NULL,
  `referral_count` int(11) NOT NULL DEFAULT 0,
  `referral_code` varchar(191) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `profiles_referral_code_unique` (`referral_code`),
  KEY `profiles_gender_id_foreign` (`gender_id`),
  KEY `profiles_marital_status_id_foreign` (`marital_status_id`),
  KEY `profiles_user_id_foreign` (`user_id`),
  KEY `profiles_company_user_id_foreign` (`company_user_id`),
  CONSTRAINT `profiles_company_user_id_foreign` FOREIGN KEY (`company_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `profiles_gender_id_foreign` FOREIGN KEY (`gender_id`) REFERENCES `genders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `profiles_marital_status_id_foreign` FOREIGN KEY (`marital_status_id`) REFERENCES `marital_statuses` (`id`) ON DELETE SET NULL,
  CONSTRAINT `profiles_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=265 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

